-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.anki_card_changes_since(since bigint, max_rows integer DEFAULT 2000)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  n integer := least(greatest(coalesce(max_rows, 2000), 1), 5000);
  page jsonb;
  last_id bigint;
  more boolean;
begin
  with rows as (
    select c.note_guid, c.ord, c.deck_id, c.change_id
      from public.anki_card_changes c
     where c.change_id > coalesce(since, 0)
     order by c.change_id
     limit n + 1
  ), firsts as (
    select * from rows order by change_id limit n
  )
  select coalesce(jsonb_agg(jsonb_build_object('noteGuid', f.note_guid, 'ord', f.ord, 'deckId', f.deck_id)
                            order by f.change_id), '[]'::jsonb),
         max(f.change_id),
         (select count(*) from rows) > n
    into page, last_id, more
    from firsts f;
  return jsonb_build_object(
    'changes', page,
    'next', coalesce(last_id, coalesce(since, 0)),
    'latest', coalesce((select max(c.change_id) from public.anki_card_changes c), 0),
    'more', more);
end;
$function$;

grant execute on function public.anki_card_changes_since(since bigint, max_rows integer) to service_role;
